-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Stateless native reads. The existing V2 host owns events and dirty bursts.
local _, ns = ...
local Adapter = {}

local function Public(api,value)
    if type(api.issecretvalue)=='function' then
        local ok,secret=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](api.issecretvalue,value)
        if not ok or secret~=false then return end
    end
    return value
end--[[APR_DIAG]]; Public = APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:10:Public#1", Public)--[[/APR_DIAG]]

local function Field(api,source,key)
    source=Public(api,source)
    if type(source)~='table' then return end
    local ok,value=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](--[[APR_DIAG]]APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:21:callback#3", --[[/APR_DIAG]]function()return source[key]end--[[APR_DIAG]])--[[/APR_DIAG]])
    if ok then return Public(api,value) end
end--[[APR_DIAG]]; Field = APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:18:Field#2", Field)--[[/APR_DIAG]]

local function Integer(value,minimum)
    return type(value)=='number' and value==value and value>=minimum
        and value<=9007199254740991 and value%1==0
end--[[APR_DIAG]]; Integer = APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:25:Integer#4", Integer)--[[/APR_DIAG]]

local function Quest(api,id)
    local fn=Field(api,api.C_QuestLog,'IsQuestFlaggedCompleted')
    if type(fn)~='function' then return end
    local ok,value=--[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](fn,id)
    if not ok then return end
    value=Public(api,value)
    if type(value)=='boolean' then return value end
end--[[APR_DIAG]]; Quest = APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:30:Quest#5", Quest)--[[/APR_DIAG]]

-- Both native clients define this character completion query and both events.
-- A nil/error/secret result is missing evidence, never an incomplete quest.
function Adapter.Capture(api,dependencies,sequence,worldState,identity,access)
    if api==nil then api=_G end
    if type(api)~='table' then return nil,'invalid_condition_api' end
    if type(dependencies)~='table' then return nil,'invalid_condition_dependencies' end
    local result={sequence=sequence,worldState=worldState or 'unknown',quests={},access={}}
    if result.worldState~='ready' then return result end
    for id in pairs(dependencies.quests or {}) do result.quests[id]=Quest(api,id) end
    for key in pairs(dependencies.access or {}) do
        local value=Field(api,access,key)
        if type(value)=='boolean' then result.access[key]=value end
    end
    for key in pairs(dependencies.identity or {}) do
        local value=Field(api,identity,key)
        if (key=='world' and Integer(value,0))
            or (key~='world' and ((type(value)=='string' and value~='') or Integer(value,0))) then
            result[key]=value
        end
    end
    return result
end--[[APR_DIAG]]; Adapter.Capture = APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:41:Adapter.Capture#6", Adapter.Capture)--[[/APR_DIAG]]

function Adapter.Events(dependencies)
    local events={}
    if type(dependencies)=='table' and type(dependencies.quests)=='table' and next(dependencies.quests) then
        events={'QUEST_LOG_UPDATE','QUEST_TURNED_IN'}
    end
    if type(dependencies)=='table' and type(dependencies.identity)=='table' and dependencies.identity.phase then
        events[#events+1]='UNIT_PHASE'
    end
    return events
end--[[APR_DIAG]]; Adapter.Events = APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:62:Adapter.Events#7", Adapter.Events)--[[/APR_DIAG]]

-- The generic update has no quest payload. A public turn-in ID can be scoped;
-- an unavailable/restricted payload conservatively dirties observed quests.
function Adapter.Affected(event,questID,dependencies,api)
    if api==nil then api=_G end
    if type(api)~='table' then return end
    if type(dependencies)~='table' then return end
    if event=='UNIT_PHASE' then
        local unit=Public(api,questID)
        if type(unit)=='string' and unit~='player' then return end
        if type(dependencies.identity)=='table' and dependencies.identity.phase then
            return {identity={phase=true}}
        end
        return
    end
    if type(dependencies.quests)~='table' then return end
    if event~='QUEST_LOG_UPDATE' and event~='QUEST_TURNED_IN' then return end
    local quests={}
    if event=='QUEST_TURNED_IN' then
        questID=Public(api,questID)
        if Integer(questID,1) then
            if dependencies.quests[questID] then quests[questID]=true end
            if not next(quests) then return end
            return {quests=quests}
        end
    end
    for id in pairs(dependencies.quests) do quests[id]=true end
    if next(quests) then return {quests=quests} end
end--[[APR_DIAG]]; Adapter.Affected = APRTrace("APR-Core/features/navigation/NavigationV2Conditions.lua:75:Adapter.Affected#8", Adapter.Affected)--[[/APR_DIAG]]

ns.NavigationV2ConditionsAdapter=Adapter
return Adapter
